/**
 * Decides whether a task update needs a status mail and builds the mail.
 *
 * Input item:  Supabase database webhook ($json.body = { type, table, record, old_record }).
 * Output item: { skip, skip_reason, to_email, subject, text }
 *
 * A mail is sent only if the status really changed to a stage with a message,
 * the creator is external and has a valid email address. Fails closed: if the
 * old status is missing, nothing is sent.
 */
const STATUS_TEXT = {
  todo: 'Your request has been accepted and is now planned.',
  in_progress: 'Work on your request has started.',
  await_feedback: 'Your request is being reviewed.',
  done: 'Your request is done.',
};
const EMAIL_PATTERN = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/;
const MAX_TITLE = 100;

const payload = $json.body ?? {};
const record = payload.record ?? {};
const oldRecord = payload.old_record ?? {};

let skipReason = '';
if (payload.type !== 'UPDATE' || payload.table !== 'tasks') skipReason = 'not a task update';
else if (!oldRecord.status) skipReason = 'old status missing';
else if (record.status === oldRecord.status) skipReason = 'status unchanged';
else if (!STATUS_TEXT[record.status]) skipReason = 'status without notification';
else if (record.creator_type !== 'external') skipReason = 'creator not external';
else if (!EMAIL_PATTERN.test(String(record.creator_email ?? ''))) skipReason = 'no creator email';

const title = String(record.title ?? '').replace(/\s+/g, ' ').trim().slice(0, MAX_TITLE);

return {
  json: {
    skip: skipReason !== '',
    skip_reason: skipReason,
    to_email: String(record.creator_email ?? '').trim().toLowerCase(),
    subject: `Update on your request: ${title}`,
    text: [
      'Hi,',
      '',
      STATUS_TEXT[record.status] ?? '',
      '',
      `Ticket: ${title}`,
      '',
      'This message was generated automatically. Please do not reply to it.',
    ].join('\n'),
  },
};
